//! Purpose:
//! Generated Rust tests for the committed PHP 8.5.10 `ext/sodium` PHPT corpus.
//!
//! Called from:
//! - `cargo test` through `tests/codegen/sodium_php_src.rs`.
//!
//! Key details:
//! - Generated by `scripts/gen_php_src_sodium_cases.py`; do not hand-edit.
//! - Each test carries its PHP source and assertion inline, and the test process
//!   never parses a `.phpt` file at run time.
//! - Every fixture is executable; php-src `SKIPIF` sections are mirrored only when
//!   the host environment itself lacks the feature under test.

#![allow(non_snake_case)]

#[allow(unused_imports)]
use super::{assert_format, assert_regex, run_case};

/// Replays php-src `bug78114.phpt`.
#[test]
fn test_php_src_sodium_bug78114() {
    let out = run_case(r#"<?php
try {
    eval('sodium_bin2hex();');
} catch (Throwable $ex) {
    echo $ex->getMessage(), PHP_EOL;
}
"#);
    assert_eq!(out.trim_matches('\n'), r#"sodium_bin2hex() expects exactly 1 argument, 0 given"#);
}

/// Replays php-src `bug78516.phpt`.
#[test]
fn test_php_src_sodium_bug78516() {
    let out = run_case(r#"<?php
$pass = password_hash('secret', PASSWORD_ARGON2ID, ['memory_cost' => 8191]);
password_needs_rehash($pass, PASSWORD_ARGON2ID, ['memory_cost' => 8191]);
var_dump(password_get_info($pass)['options']['memory_cost']);
$pass = password_hash('secret', PASSWORD_ARGON2I, ['memory_cost' => 8191]);
password_needs_rehash($pass, PASSWORD_ARGON2I, ['memory_cost' => 8191]);
var_dump(password_get_info($pass)['options']['memory_cost']);
"#);
    assert_eq!(out.trim_matches('\n'), r#"int(8191)
int(8191)"#);
}

