$c2 = sodium_crypto_secretstream_xchacha20poly1305_push($stream, $msg2, '', SODIUM_CRYPTO_SECRETSTREAM_XCHACHA20POLY1305_TAG_FINAL);

$stream = sodium_crypto_secretstream_xchacha20poly1305_init_pull($header, $key);

